func ttFixture(emonT *testing.T, file []byte, wantFa int32, wantHidden int32, wantRows int32, ctx int32) int32 {
	// Run one document through the document pass up to the ledger and check what the laws above say; the numbers are
	// the fixture's (`want-fa` set-aside words, `want-hidden` hidden-text words left in the flow, `want-rows` ledger rows).
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var cx *port.Cells = port.NewCells()
	var ox *port.Cells = port.NewCells()
	var cs *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var f0 *port.Cells = port.NewCells()
	var f1 *port.Cells = port.NewCells()
	var f2 *port.Cells = port.NewCells()
	var f3 *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var fnt *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var pa *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var gx *port.Cells = port.NewCells()
	var epages *port.Cells = port.NewCells()
	var feats *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var fl *port.Cells = port.NewCells()
	var fa *port.Cells = port.NewCells()
	var hl *port.Cells = port.NewCells()
	var sc *port.Cells = port.NewCells()
	var cg *port.Cells = port.NewCells()
	var fv *port.Cells = port.NewCells()
	var fx *port.Cells = port.NewCells()
	var fpa *port.Cells = port.NewCells()
	var sl *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var tt *port.Cells = port.NewCells()
	var fw2 *port.Cells = port.NewCells()
	var fl2 *port.Cells = port.NewCells()
	var src *port.Src = port.SrcOfBlob(file)
	var o int32 = pdfdoc.PdOpen(src, ar, dc, a, b, st)
	var status int32 = 0
	var i int32 = 0
	var hidden int32 = 0
	var total int32 = 0
	var w int32 = 0
	var g0 int32 = 0
	var ft int32 = 0
	var vis int32 = 0
	var rows int32 = 0
	port.AssertEqAt(emonT, o, 0, "the file opened", ctx)
	status = pdfcontent.PcDocument(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx)
	port.AssertEqAt(emonT, status, 0, "the file ran", ctx)
	tlhealth.ThRun(pg, gl, et, mk, fnt, wd, ln, im, epages, feats, fw, fl, fa, hl, sc)
	// the flow and the set-aside are every word
	port.AssertEqAt(emonT, player.FwCount(fw)+player.FaCount(fa), evidence.WdCount(wd), "fw + fa is every word", ctx)
	port.AssertEqAt(emonT, player.FaCount(fa), wantFa, "set-aside words", ctx)
	// no failed word in the flow, but a hidden OCR layer under a page-sized image
	i = 0
	for i < player.FwCount(fw) {
		g0 = port.CellsAt(fw, (i*24)+17)
		vis = evidence.GlGet(gl, g0, evidence.GfVis())
		if (port.CellsAt(fw, (i*24)+23) & 2) == 2 {
			hidden += 1
		}
		if vis != 0 {
			port.AssertEqAt(emonT, vis, evidence.VzOccluded(), "only an occluded word stays", ctx)
			port.AssertEqAt(emonT, port.CellsAt(fw, (i*24)+23), model.SrHiddenText(), "and as hidden-text", ctx)
		}
		ft = port.CellsAt(fw, (i*24)+15)
		port.AssertThatAt(emonT, ft >= 0, "every word has a feature row", ctx)
		port.AssertEqAt(emonT, evidence.FeGet(feats, ft, evidence.XtLength()), port.CellsAt(fw, (i*24)+12), "its length", ctx)
		port.AssertEqAt(emonT, evidence.FeGet(feats, ft, evidence.XtVis()), vis, "its worst vis", ctx)
		i += 1
	}
	port.AssertEqAt(emonT, hidden, wantHidden, "hidden-text words left in the flow", ctx)
	// every set-aside word failed a check, under the reason its class says
	i = 0
	for i < player.FaCount(fa) {
		w = player.FaGet(fa, i, 7)
		vis = evidence.GlGet(gl, evidence.WdGet(wd, w, evidence.WfGfirst()), evidence.GfVis())
		port.AssertThatAt(emonT, vis != 0, "a set-aside word failed a check", ctx)
		if vis == 1 {
			port.AssertEqAt(emonT, player.FaGet(fa, i, 5), model.DrClipped(), "clipped", ctx)
		}
		if vis == 2 {
			port.AssertEqAt(emonT, player.FaGet(fa, i, 5), model.DrOffpage(), "offpage", ctx)
		}
		if vis > 2 {
			port.AssertThatAt(emonT, (player.FaGet(fa, i, 5) == model.DrInvisible()) || (player.FaGet(fa, i, 5) == model.DrWatermark()), "invisible (or a watermark)", ctx)
		}
		i += 1
	}
	// the lines are what is left
	i = 0
	total = 0
	for i < player.FlCount(fl) {
		port.AssertThatAt(emonT, port.CellsAt(fl, (i*16)+12) > 0, "no empty line", ctx)
		port.AssertEqAt(emonT, port.CellsAt(fl, (i*16)+11), total, "the lines run over the words in order", ctx)
		total += port.CellsAt(fl, (i*16)+12)
		i += 1
	}
	port.AssertEqAt(emonT, total, player.FwCount(fw), "the lines hold every word", ctx)
	port.AssertThatAt(emonT, player.FlCount(fl) <= evidence.LnCount(ln), "no line is made", ctx)
	port.AssertEqAt(emonT, player.PlCheck(cg, fw, fl, fv, fa, fx, hl, fpa, sl, et, refs, gl), 0, "the layer is sound", ctx)
	// the OCR lines of a scanned page join the flow as they are: every line and word of the evidence, copied
	port.AssertEqAt(emonT, tlhealth.ThAppend(wd, ln, fw2, fl2, 0), evidence.LnCount(ln), "every line is copied", ctx)
	port.AssertEqAt(emonT, player.FwCount(fw2), evidence.WdCount(wd), "and every word", ctx)
	port.AssertEqAt(emonT, player.PlCheck(cg, fw2, fl2, fv, fa, fx, hl, fpa, sl, et, refs, gl), 0, "the copy is sound", ctx)
	// the ledger
	rows = tlhealth.ThWrite(fa, wd, et, ledger, text, tmp, tt)
	port.AssertEqAt(emonT, rows, wantRows, "ledger rows", ctx)
	port.AssertEqAt(emonT, model.LedgerCount(ledger), wantRows, "ledger rows written", ctx)
	i = 0
	for i < rows {
		port.AssertThatAt(emonT, model.LedgerTextLen(ledger, i) > 0, "a ledger row has its text", ctx)
		i += 1
	}
	// the page table: a row for every page, with its size and its text layer
	port.AssertEqAt(emonT, evidence.EpCount(epages), pdfdoc.PdPgCount(pg), "an epages row for every page", ctx)
	i = 0
	for i < evidence.EpCount(epages) {
		port.AssertThatAt(emonT, evidence.EpGet(epages, i, evidence.EpfWidth()) > 0, "a page has a width", ctx)
		port.AssertThatAt(emonT, evidence.EpGet(epages, i, evidence.EpfHeight()) > 0, "a page has a height", ctx)
		i += 1
	}
	return player.HlCount(hl)
}

