func TestHealthScores(emonT *testing.T) {
	port.AssertEq(emonT, tlhealth.ThScore(1000, 0, 0, 0), 1000, "a perfect font")
	port.AssertEq(emonT, tlhealth.ThScore(1000, 0, 500, 500), 1000, "the limits are free")
	port.AssertThat(emonT, tlhealth.ThScore(1000, 0, 100, 0) >= tlhealth.ThTrusted(), "a normal font is trusted")
	port.AssertThat(emonT, tlhealth.ThScore(0, 1000, 0, 0) < 300, "an unmapped font is far under 300")
	port.AssertThat(emonT, tlhealth.ThScore(500, 0, 0, 0) < tlhealth.ThTrusted(), "half unmapped is not trusted")
	port.AssertThat(emonT, tlhealth.ThScore(1000, 0, 1000, 0) < tlhealth.ThAutoHealth(), "every glyph on its neighbour is not healthy")
	port.AssertThat(emonT, tlhealth.ThScore(1000, 0, 0, 3000) < tlhealth.ThAutoHealth(), "words torn apart are not healthy")
	port.AssertThat(emonT, tlhealth.ThScore(1000, 500, 0, 0) < tlhealth.ThTrusted(), "half garbage is not trusted")
	port.AssertThat(emonT, tlhealth.ThScore(800, 0, 0, 0) > tlhealth.ThScore(600, 0, 0, 0), "more mapped, better")
}

func ttHealth(file []byte, which int32) int32 {
	// Run a document to its health rows; answer, for which 0 the rows, 1 how many are at least `tl-trusted`, 2 the lowest score,
	// 3 the highest score of the rows that are not at least `tl-trusted`.
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var cx *port.Cells = port.NewCells()
	var ox *port.Cells = port.NewCells()
	var cs *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var f0 *port.Cells = port.NewCells()
	var f1 *port.Cells = port.NewCells()
	var f2 *port.Cells = port.NewCells()
	var f3 *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var fnt *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var pa *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var gx *port.Cells = port.NewCells()
	var epages *port.Cells = port.NewCells()
	var feats *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var fl *port.Cells = port.NewCells()
	var fa *port.Cells = port.NewCells()
	var hl *port.Cells = port.NewCells()
	var sc *port.Cells = port.NewCells()
	var src *port.Src = port.SrcOfBlob(file)
	var o int32 = pdfdoc.PdOpen(src, ar, dc, a, b, st)
	var i int32 = 0
	var good int32 = 0
	var low int32 = 100000
	var high int32 = 0
	if o != 0 {
		return -1
	}
	pdfcontent.PcDocument(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx)
	tlhealth.ThRun(pg, gl, et, mk, fnt, wd, ln, im, epages, feats, fw, fl, fa, hl, sc)
	for i < player.HlCount(hl) {
		if player.HlGet(hl, i, player.HlfScore()) >= tlhealth.ThTrusted() {
			good += 1
		} else if player.HlGet(hl, i, player.HlfScore()) > high {
			high = player.HlGet(hl, i, player.HlfScore())
		}
		if player.HlGet(hl, i, player.HlfScore()) < low {
			low = player.HlGet(hl, i, player.HlfScore())
		}
		i += 1
	}
	if which == 0 {
		return player.HlCount(hl)
	}
	if which == 1 {
		return good
	}
	if which == 2 {
		return low
	}
	return high
}

func TestAnUnmappedFontIsCaughtAndAShiftedOneIsNot(emonT *testing.T) {
	// tl-broken-unmapped: one font whose glyphs have no Unicode (score far under 300); every other font of both pages is trusted
	port.AssertEq(emonT, ttHealth(port.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), 0), 7, "unmapped: rows")
	port.AssertEq(emonT, ttHealth(port.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), 1), 5, "unmapped: trusted rows")
	port.AssertThat(emonT, ttHealth(port.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), 2) < 300, "unmapped: the broken font is under 300")
	// tl-broken-shift: a plausible mapping that is wrong; the text layer cannot tell, OCR agreement can (P7.2)
	port.AssertEq(emonT, ttHealth(port.TestFile("corpus/synth/pdf/tl-broken-shift.pdf"), 0), ttHealth(port.TestFile("corpus/synth/pdf/tl-broken-shift.pdf"), 1), "shifted: every font passes")
}

func TestHealthyDocumentsAreTrusted(emonT *testing.T) {
	port.AssertEq(emonT, ttHealth(port.TestFile("corpus/synth/pdf/align-rtl.pdf"), 0), ttHealth(port.TestFile("corpus/synth/pdf/align-rtl.pdf"), 1), "rtl")
	port.AssertEq(emonT, ttHealth(port.TestFile("corpus/synth/pdf/bank-statement.pdf"), 0), ttHealth(port.TestFile("corpus/synth/pdf/bank-statement.pdf"), 1), "bank statement")
	port.AssertEq(emonT, ttHealth(port.TestFile("vis/visible.pdf"), 0), ttHealth(port.TestFile("vis/visible.pdf"), 1), "visible")
}
